(()=>{
'use strict';
const D=window.STUDY_DATA,root=document.querySelector('#page-content');
if(!D||!Array.isArray(D.subjects)||!Array.isArray(D.exams)||!Array.isArray(D.questions)){
 root.innerHTML='<section class="panel"><h1>Study content unavailable</h1><p>Reload while online so the content files can be cached.</p></section>';return;
}
const KEY='beu-cse-sem4-tracker-local-v1',STATUSES=['Not started','Learning','Practiced','Recall passed','Exam-ready','Needs revision'];
const WEIGHT={'Not started':0,'Learning':.25,'Practiced':.5,'Recall passed':.75,'Exam-ready':1,'Needs revision':.35};
const SUBJECTS=D.subjects,EXAMS=D.exams;
const SHORT=[
{id:'short-cn-1',s:'CN',type:'Short',q:'Define bandwidth, throughput, latency and jitter.',a:'Bandwidth is link capacity; throughput is the achieved delivery rate; latency is end-to-end delay; jitter is variation in delay.'},
{id:'short-cn-2',s:'CN',type:'Short',q:'Differentiate circuit switching and packet switching.',a:'Circuit switching reserves dedicated resources for a session. Packet switching forwards packets over shared links; it uses bandwidth flexibly but can introduce queueing delay.'},
{id:'short-coa-1',s:'COA',type:'Short',q:'Differentiate hardwired and microprogrammed control units.',a:'Hardwired control generates signals through fixed logic and is usually faster but harder to modify. Microprogrammed control uses control memory and is easier to modify, but may be slower.'},
{id:'short-coa-2',s:'COA',type:'Short',q:'What is a pipeline hazard?',a:'A pipeline hazard prevents an instruction from executing in its intended cycle. Common types are structural, data and control hazards.'},
{id:'short-flat-1',s:'FLAT',type:'Short',q:'Define DFA and NFA.',a:'A DFA has exactly one transition per state/input-symbol pair. An NFA can have multiple possible transitions and may allow epsilon transitions. Both recognise the regular languages.'},
{id:'short-flat-2',s:'FLAT',type:'Short',q:'What is an ambiguous context-free grammar?',a:'A CFG is ambiguous if a string in its language has two distinct parse trees, equivalently two distinct leftmost derivations.'},
{id:'short-daa-1',s:'DAA',type:'Short',q:'Define time complexity and space complexity.',a:'Time complexity describes how computation work grows with input size; space complexity describes memory use as a function of input size, typically with asymptotic bounds.'},
{id:'short-daa-2',s:'DAA',type:'Short',q:'Differentiate greedy algorithms and dynamic programming.',a:'Greedy algorithms commit to a locally optimal choice. Dynamic programming stores and combines subproblem results, especially when optimal substructure and overlapping subproblems exist.'},
{id:'short-dbms-1',s:'DBMS',type:'Short',q:'Define primary key, candidate key and foreign key.',a:'A candidate key is a minimal attribute set that uniquely identifies a row. A primary key is the selected candidate key. A foreign key references a key in another or the same relation.'},
{id:'short-dbms-2',s:'DBMS',type:'Short',q:'What is a functional dependency?',a:'X → Y means any two valid tuples agreeing on attribute set X must also agree on attribute set Y.'},
{id:'short-etc-1',s:'ETC',type:'Short',q:'Define technical communication.',a:'Technical communication conveys specialized information to a defined audience for a practical purpose through documents, diagrams, presentations or other suitable channels.'},
{id:'short-etc-2',s:'ETC',type:'Short',q:'What is the purpose of an executive summary?',a:'It provides a concise, largely standalone overview of a report’s purpose, context, main findings and recommendations.'}
];
const BASE=()=>({version:1,onboarded:false,prefs:{hours:6,mode:'Balanced',name:'',prep:25,theme:'light',language:'en',notifications:false,semester:'4',branch:'CSE'},topics:{},dayDone:{},plans:{},notes:[],mistakes:[],scores:[],sessions:[],questionAnswers:{},bookmarks:[],flashcards:{},examChecks:{}});
function loadState(){
 try{const old=JSON.parse(localStorage.getItem(KEY));if(!old||old.version!==1)return BASE();const b=BASE();return {...b,...old,prefs:{...b.prefs,...(old.prefs||{})},topics:old.topics||{},dayDone:old.dayDone||{},plans:old.plans||{},notes:Array.isArray(old.notes)?old.notes:[],mistakes:Array.isArray(old.mistakes)?old.mistakes:[],scores:Array.isArray(old.scores)?old.scores:[],sessions:Array.isArray(old.sessions)?old.sessions:[],questionAnswers:old.questionAnswers||{},bookmarks:Array.isArray(old.bookmarks)?old.bookmarks:[],flashcards:old.flashcards||{},examChecks:old.examChecks||{}};}catch(_){return BASE();}
}
let state=loadState(),route=parseRoute(location.hash),selectedSubject='COA',selectedQuestion='',subjectFilter='ALL',questionType='ALL',questionSearch='',pyqYear='ALL',pyqMarks='ALL',pyqPriority='ALL',pyqUnit='ALL',pyqTopic='ALL',pyqSource='ALL',pyqCompletion='ALL',quizState=null,installPrompt=null,moreOpen=false,notesTab='notes',revisionIndex=0,pdfDb=null,activePdfUrl=null;
let lastFilterHash='';
let onboardingDraft={hours:state.prefs.hours||6,mode:state.prefs.mode||'Balanced',name:state.prefs.name||'',theme:state.prefs.theme||'light',language:state.prefs.language||'en'};
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
function parseRoute(hash){let p=(hash||'').replace(/^#\/?/,'').split('?')[0].split('/').filter(Boolean);let page=p[0]||'dashboard',param=p[1]||'';if(page==='home')page='dashboard';if(page==='subjects'&&param)return {page:'subject',param};if(page==='topics')return {page:'topic',param};if(page==='questions')return {page:'question',param};if(page==='results')return {page:'results',param};if(!['dashboard','subjects','subject','topic','syllabus','planner','pyqs','question','practice','results','revision','resources','exams','progress','saved','notes','settings','welcome','onboarding'].includes(page))page='dashboard';return {page,param};}
function today(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function dateLabel(s,opts={day:'numeric',month:'short',year:'numeric'}){return new Date(s+'T12:00:00').toLocaleDateString('en-IN',opts);}
function daysUntil(s){return Math.ceil((new Date(s+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));const x=$('#save-status');if(x)x.textContent='Saved on this device';return true;}catch(_){toast('Browser storage is full. Export a backup in Profile & settings.');return false;}}
function toast(msg){const e=$('#toast');e.textContent=msg;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,3000);}
function subj(id){return SUBJECTS.find(s=>s.id===id);}
function getExam(id){return EXAMS.find(e=>e.id===id);}
function flattenTopics(){return SUBJECTS.flatMap(s=>s.units.flatMap((u,unitIndex)=>u.topics.map((t,topicIndex)=>({id:s.id+'-'+unitIndex+'-'+topicIndex,s:s.id,subject:s,unit:u.name,unitIndex,topicIndex,name:t[0],priority:t[1],hours:u.hours}))));}
const ALL_TOPICS=flattenTopics();
function topicById(id){return ALL_TOPICS.find(t=>t.id===id);}
function topicStatus(t){return state.topics[t.id]?.status||'Not started';}
function recalled(t){return ['Recall passed','Exam-ready'].includes(topicStatus(t));}
function subjectProgress(s){const a=ALL_TOPICS.filter(t=>t.s===s.id);return a.length?Math.round(a.reduce((n,t)=>n+(WEIGHT[topicStatus(t)]||0),0)/a.length*100):0;}
function overallProgress(){return ALL_TOPICS.length?Math.round(ALL_TOPICS.reduce((n,t)=>n+(WEIGHT[topicStatus(t)]||0),0)/ALL_TOPICS.length*100):0;}
function countRecalled(a){return a.filter(recalled).length;}
function heading(title,desc,actions=''){return '<div class="page-heading"><div class="page-heading-main"><div class="eyebrow">BEU EXAM PREP · B.Tech CSE · Semester 04</div><h1>'+title+'</h1><p>'+desc+'</p></div>'+(actions?'<div class="heading-actions">'+actions+'</div>':'')+'</div>';}
function badge(text,kind=''){return '<span class="badge '+(kind?'badge-'+kind:'')+'">'+text+'</span>';}
function meter(v,variant=''){return '<div class="progress"><div class="progress-fill '+variant+'" style="width:'+Math.max(0,Math.min(100,v))+'%"></div></div>';}
function metric(icon,value,label,caption='',variant=''){return '<div class="panel metric"><div class="metric-icon '+variant+'">'+icon+'</div><div><div class="metric-value">'+value+'</div><div class="metric-label">'+label+'</div>'+(caption?'<div class="metric-caption">'+caption+'</div>':'')+'</div></div>';}
function priorityTag(p){return '<span class="topic-priority priority-'+p.toLowerCase()+'">'+p+' priority</span>';}
function statusTag(s){return '<span class="topic-status '+s.toLowerCase().replaceAll(' ','-')+'">'+esc(s)+'</span>';}
function chatLink(p){return 'https://chatgpt.com/?q='+encodeURIComponent(p);}
function activeExam(){return EXAMS.find(e=>e.date>=today())||EXAMS[EXAMS.length-1];}
function examRow(e){const d=daysUntil(e.date),label=d<0?'Completed':d===0?'Today':d+' days left';return '<div class="exam-row"><div class="exam-date-block"><strong>'+new Date(e.date+'T12:00:00').getDate()+'</strong><small>'+new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})+'</small></div><div class="exam-info"><div class="exam-title">'+esc(e.name)+'</div><div class="exam-code">'+e.code+' · 2:00–5:00 PM</div></div><div class="exam-countdown">'+label+'</div></div>';}
function subjectCards(){return '<div class="grid grid-3">'+SUBJECTS.map(s=>{const a=ALL_TOPICS.filter(t=>t.s===s.id);return '<button type="button" class="panel subject-card" data-go="#/subjects/'+s.id+'" style="width:100%;text-align:left"><div class="subject-top"><div class="subject-icon" style="background:'+s.color+'20;color:'+s.color+'">'+esc(s.icon)+'</div><div style="min-width:0"><div class="subject-title">'+esc(s.name)+'</div><div class="subject-code">'+s.code+' · '+s.units.length+' units</div></div><div class="subject-percent">'+subjectProgress(s)+'%</div></div><div class="subject-foot"><span>'+countRecalled(a)+'/'+a.length+' recalled</span><span>'+a.length+' topics</span></div>'+meter(subjectProgress(s))+'</button>';}).join('')+'</div>';}
function sortTopics(sid){const rank={High:0,Medium:1,Low:2};return ALL_TOPICS.filter(t=>t.s===sid&&!['Exam-ready','Recall passed'].includes(topicStatus(t))).sort((a,b)=>{if(state.prefs.mode!=='Balanced')return rank[a.priority]-rank[b.priority];return (getExam(a.s)?.date||'2999').localeCompare(getExam(b.s)?.date||'2999')||rank[a.priority]-rank[b.priority];});}
function makePlanTopics(force=false){
 const day=today();if(force)delete state.plans[day];if(Array.isArray(state.plans[day])&&!force){const saved=state.plans[day].map(topicById).filter(Boolean);if(saved.length)return saved;}
 const first=activeExam();let eve=new Date(first.date+'T12:00:00');eve.setDate(eve.getDate()-1);
 let focus;if(day===first.date||eve.toISOString().slice(0,10)===day)focus=[first.id];else{focus=EXAMS.filter(e=>e.date>=day).slice(0,3).map(e=>e.id);if(!focus.includes('DBMS')&&daysUntil('2026-11-03')>=0&&daysUntil('2026-11-03')<=11)focus.push('DBMS');}
 const candidates=focus.flatMap(sortTopics),slots=({4:4,6:5,8:7,12:9})[Number(state.prefs.hours)]||5,chosen=[],seen=new Set(),rank={High:0,Medium:1,Low:2};
 if(state.prefs.mode==='Crash course')candidates.sort((a,b)=>rank[a.priority]-rank[b.priority]);
 for(const id of focus){const t=candidates.find(x=>x.s===id&&!seen.has(x.id));if(t&&chosen.length<slots){chosen.push(t);seen.add(t.id);}}
 for(const t of candidates){if(chosen.length>=slots)break;if(!seen.has(t.id)){chosen.push(t);seen.add(t.id);}}
 if(!chosen.length)chosen.push(...ALL_TOPICS.filter(t=>!recalled(t)).slice(0,slots));
 state.plans[day]=chosen.map(t=>t.id);save();return chosen;
}
function planTasks(){const a=makePlanTopics(),mins=Math.max(20,Math.floor(Number(state.prefs.hours||6)*60/Math.max(1,a.length)));return a.map(t=>({id:today()+':'+t.id,topic:t,mins:Math.min(90,mins)}));}
function taskCard(task){const done=!!state.dayDone[task.id],t=task.topic;return '<div class="task-row '+(done?'is-done':'')+'"><button type="button" class="task-toggle '+(done?'checked':'')+'" data-plan-toggle="'+esc(task.id)+'" aria-label="'+(done?'Mark incomplete':'Mark complete')+'">'+(done?'✓':'')+'</button><div class="task-content"><div class="task-title">'+esc(t.name)+'</div><div class="task-meta">'+esc(t.subject.short)+' · '+task.mins+' min · '+t.priority+' priority</div><div class="task-actions"><button class="btn btn-sm btn-quiet" data-topic-note="'+t.id+'">Add note</button><a class="btn btn-sm btn-quiet" target="_blank" rel="noopener" href="'+chatLink('Teach me '+t.name+' for BEU B.Tech CSE Semester 4. Explain step by step with an example and finish with an exam-ready answer.')+'">Study help ↗</a></div></div></div>';}
function dashboardPage(){const tasks=planTasks(),done=tasks.filter(t=>state.dayDone[t.id]).length,e=activeExam();return heading('Your study desk','Know what to study next, why it matters and what to practise.','<button class="btn btn-primary" data-go="#/planner">Open study plan →</button>')+
'<section class="hero-card"><div class="hero-eyebrow">✦ YOUR SEMESTER, WELL PLANNED</div><h1 class="hero-title">'+(state.prefs.name?'Welcome back, '+esc(state.prefs.name)+'.':'Small study blocks. Strong answers.')+'</h1><p class="hero-description">'+Number(state.prefs.hours)+' hours per day · '+esc(state.prefs.mode)+' preparation. Your progress is saved privately in this browser.</p><div class="hero-actions"><button class="btn btn-primary" data-go="#/planner">Start today’s plan</button><button class="btn" data-go="#/subjects">Continue subjects</button><button class="btn btn-quiet" data-go="#/practice">Test my recall ↗</button></div></section>'+
'<div class="grid grid-4">'+metric('◉',overallProgress()+'%','Topic mastery','Status-weighted')+metric('✓',ALL_TOPICS.filter(recalled).length,'Topics recalled','Recall passed or exam-ready','mint')+metric('◷',Number(state.prefs.hours)+'h','Daily target',state.prefs.mode,'blue')+metric('✎',state.scores.length,'Test attempts','Saved on this device','amber')+'</div>'+
'<div class="section-heading"><div><h2>Today’s focus</h2><p>Complete a block after doing the recall or practice.</p></div><button class="inline-link" data-go="#/planner">Full plan →</button></div><div class="section-grid"><section class="panel"><div class="progress-meta"><span>'+done+' of '+tasks.length+' blocks complete</span><span>'+Math.round(done/Math.max(1,tasks.length)*100)+'%</span></div>'+meter(done/Math.max(1,tasks.length)*100,'mint')+'<div style="margin-top:9px">'+tasks.slice(0,4).map(taskCard).join('')+'</div><div class="task-actions"><button class="btn btn-primary" data-go="#/planner">View plan</button><button class="btn btn-quiet" data-action="log-session">Log study time</button></div></section><div class="content-stack"><section class="panel panel-elevated"><div class="eyebrow">NEXT EXAM</div><h2 style="font-size:19px">'+esc(e.name)+'</h2><p class="muted text-sm">'+dateLabel(e.date)+' · '+e.code+'</p><div class="line"></div><div class="exam-countdown" style="font-size:14px">'+(daysUntil(e.date)===0?'Exam day':daysUntil(e.date)<0?'Schedule completed':daysUntil(e.date)+' days to go')+'</div><p class="muted text-sm">Paper time: 2:00–5:00 PM. Practise structured answers and closed-book recall.</p><button class="btn btn-sm" data-go="#/exams">Exam calendar →</button></section><section class="panel"><h2>A repeatable learning loop</h2><div class="mini-list"><div class="mini-list-item"><span class="mini-dot"></span>Understand one defined concept.</div><div class="mini-list-item"><span class="mini-dot"></span>Reproduce it without notes.</div><div class="mini-list-item"><span class="mini-dot"></span>Attempt a question or numerical.</div><div class="mini-list-item"><span class="mini-dot"></span>Log the exact gap and revisit it.</div></div></section></div></div>'+
'<div class="section-heading"><div><h2>Your subjects</h2><p>Open a subject to work through its units and topics.</p></div><button class="inline-link" data-go="#/subjects">All subjects →</button></div>'+subjectCards()+
'<div class="section-heading"><div><h2>Exam calendar</h2><p>Dates copied from the routine you provided.</p></div><button class="inline-link" data-go="#/exams">Full timetable →</button></div><section class="panel">'+EXAMS.map(examRow).join('')+'</section><footer class="seo-note"><strong>Academic accuracy</strong><p>Priority labels are study guidance, not official marks weightage. Curated practice questions are not presented as a verbatim archive of every PYQ. Verify exam dates against any later notice.</p></footer>';}
function subjectsPage(){return heading('My subjects','Explore each paper, track unit-wise coverage, and open individual learning checkpoints.')+'<div class="filters-bar"><div class="filter-pills">'+[['ALL','All subjects'],...SUBJECTS.map(s=>[s.id,s.short+' · '+s.code])].map(([v,l])=>'<button class="filter-pill '+(subjectFilter===v?'active':'')+'" data-subject-filter="'+v+'">'+esc(l)+'</button>').join('')+'</div></div><div class="grid grid-3">'+SUBJECTS.filter(s=>subjectFilter==='ALL'||s.id===subjectFilter).map(s=>{const a=ALL_TOPICS.filter(t=>t.s===s.id);return '<article class="panel"><div class="subject-top"><div class="subject-icon" style="background:'+s.color+'20;color:'+s.color+'">'+esc(s.icon)+'</div><div style="flex:1;min-width:0"><div class="subject-title">'+esc(s.name)+'</div><div class="subject-code">'+s.code+' · '+s.units.length+' units</div></div></div><div class="progress-meta"><span>'+countRecalled(a)+'/'+a.length+' recalled</span><strong>'+subjectProgress(s)+'%</strong></div>'+meter(subjectProgress(s))+'<div class="task-actions"><button class="btn btn-primary" data-go="#/subjects/'+s.id+'">Open subject →</button><button class="btn btn-sm" data-go="#/pyqs?subject='+s.id+'">Related PYQs</button></div></article>';}).join('')+'</div>';}
function subjectDetailPage(id){const s=subj(id);if(!s)return emptyRoute('Subject not found','Return to subjects.','#/subjects');const all=ALL_TOPICS.filter(t=>t.s===s.id);return heading(esc(s.name),'Course code '+s.code+'. Study the unit structure, then practise and track recall.','<button class="btn" data-go="#/subjects">← All subjects</button>')+'<section class="hero-card"><div class="hero-eyebrow">'+esc(s.short)+' · '+s.code+'</div><h1 class="hero-title">'+subjectProgress(s)+'% mastery tracked</h1><p class="hero-description">'+countRecalled(all)+' of '+all.length+' topics marked recall-passed or exam-ready. Priority labels are study guidance, not official marks weightage.</p>'+meter(subjectProgress(s))+'<div class="hero-actions" style="margin-top:16px"><button class="btn btn-primary" data-go="#/syllabus?subject='+s.id+'">Open unit checklist</button><button class="btn" data-go="#/pyqs?subject='+s.id+'">Related questions</button><button class="btn" data-go="#/practice?subject='+s.id+'">Practise this subject</button></div></section><div class="grid grid-2">'+s.units.map((u,ui)=>{const ts=all.filter(t=>t.unitIndex===ui),done=countRecalled(ts);return '<section class="panel"><div class="question-top"><span class="unit-number">'+(ui+1)+'</span>'+badge(done+'/'+ts.length+' recalled','purple')+'</div><h2 style="margin-top:12px">'+esc(u.name)+'</h2><p class="muted text-sm">'+u.hours+' syllabus hours · '+ts.length+' topics</p>'+meter(done/Math.max(1,ts.length)*100)+'<div class="mini-list" style="margin-top:12px">'+ts.slice(0,5).map(t=>'<button class="mini-list-item" style="border:0;background:none;text-align:left;padding:2px 0" data-go="#/topics/'+t.id+'"><span class="mini-dot"></span>'+esc(t.name)+'</button>').join('')+(ts.length>5?'<span class="muted text-xs">+'+(ts.length-5)+' more topics</span>':'')+'</div><div class="task-actions"><button class="btn btn-sm" data-go="#/syllabus?subject='+s.id+'">Unit tracker →</button></div></section>';}).join('')+'</div>';}
function syllabusPage(){const chosen=subjectFilter==='ALL'?SUBJECTS:SUBJECTS.filter(s=>s.id===subjectFilter);let out=heading('Syllabus tracker','Unit-by-unit checklist based on the supplied syllabus compilation. Set an honest recall status to update progress.','<button class="btn" data-go="#/resources">My references ↗</button>')+'<div class="filters-bar"><div class="filter-pills">'+[['ALL','All subjects'],...SUBJECTS.map(s=>[s.id,s.short])].map(([id,label])=>'<button class="filter-pill '+(subjectFilter===id?'active':'')+'" data-subject-filter="'+id+'">'+label+'</button>').join('')+'</div></div>';for(const s of chosen){const all=ALL_TOPICS.filter(t=>t.s===s.id);out+='<div class="section-heading"><div class="subject-top"><div class="subject-icon" style="background:'+s.color+'20;color:'+s.color+'">'+esc(s.icon)+'</div><div><h2>'+esc(s.name)+'</h2><p>'+s.code+' · '+s.units.length+' units · '+all.length+' checkpoints</p></div></div><span class="badge badge-purple">'+subjectProgress(s)+'% progress</span></div><div class="progress-meta"><span>'+countRecalled(all)+' topics recalled</span><span>'+all.length+' topics</span></div>'+meter(subjectProgress(s));s.units.forEach((u,ui)=>{const ts=all.filter(t=>t.unitIndex===ui),done=countRecalled(ts);out+='<details class="panel unit-card" '+(ui===0?'open':'')+'><summary class="unit-header"><span class="unit-number">'+String(ui+1).padStart(2,'0')+'</span><span class="unit-header-title"><strong>'+esc(u.name)+'</strong><small>'+u.hours+' syllabus hours · '+done+'/'+ts.length+' recalled</small></span><span class="unit-chevron">⌄</span></summary><div class="unit-body">';ts.forEach(t=>{const st=topicStatus(t);out+='<div class="topic-row"><button class="topic-check '+(recalled(t)?'checked':'')+'" data-quick-toggle="'+t.id+'" aria-label="Toggle recall status">'+(recalled(t)?'✓':'')+'</button><div class="topic-main"><div class="topic-name">'+esc(t.name)+'</div><div class="topic-detail">'+priorityTag(t.priority)+statusTag(st)+'</div><div class="task-actions"><select class="field-control" style="width:auto;max-width:175px;padding:7px 9px" data-topic-status="'+t.id+'" aria-label="Set topic status">'+STATUSES.map(v=>'<option '+(v===st?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select><button class="btn btn-sm btn-quiet" data-topic-note="'+t.id+'">Add note</button><button class="btn btn-sm btn-quiet" data-go="#/topics/'+t.id+'">Learn topic →</button></div></div></div>';});out+='</div></details>';});}return out+'<section class="panel"><h2>When to mark a topic done</h2><div class="grid grid-3"><div>'+statusTag('Learning')+'<p class="muted text-sm">You can explain the basics with notes.</p></div><div>'+statusTag('Practiced')+'<p class="muted text-sm">You solved a numerical, drew a diagram or wrote an answer.</p></div><div>'+statusTag('Recall passed')+' '+statusTag('Exam-ready')+'<p class="muted text-sm">You reproduce key points closed-book; exam-ready also means timed practice.</p></div></div></section>';}
function topicPage(id){const t=topicById(id);if(!t)return emptyRoute('Topic not found','Choose a topic from the syllabus.','#/syllabus');const s=t.subject,u=s.units[t.unitIndex],siblings=ALL_TOPICS.filter(x=>x.s===t.s),idx=siblings.findIndex(x=>x.id===t.id),prev=siblings[idx-1],next=siblings[idx+1],st=topicStatus(t);const rel=questionBank().filter(q=>q.s===t.s&&((q.q||'').toLowerCase().includes(t.name.split(/[ ,:;]/)[0].toLowerCase())||q.type==='MCQ')).slice(0,4);return heading('Topic learning',esc(s.name)+' · '+esc(u.name),'<button class="btn" data-go="#/subjects/'+s.id+'">← Subject</button>')+'<section class="panel"><div class="question-top"><div><div class="eyebrow">'+esc(s.short)+' · TOPIC '+(idx+1)+' OF '+siblings.length+'</div><h2 style="font-size:22px;margin:6px 0">'+esc(t.name)+'</h2></div>'+priorityTag(t.priority)+'</div><div class="topic-detail">'+statusTag(st)+badge(s.code)+'</div><div class="line"></div><h2>Study this topic</h2><p class="muted" style="line-height:1.8">This topic is part of the supplied syllabus structure. Use the outline below to create exam-ready notes, then verify the details against your course material. The app does not invent a full textbook explanation where one has not been verified.</p><div class="answer-outline"><strong>A useful learning sequence</strong><ol><li>Write a precise definition and identify the notation/terminology.</li><li>Explain the core mechanism or theorem in ordered steps.</li><li>Work through one representative example, numerical or diagram.</li><li>Close notes and reproduce the explanation in the form expected for the question’s marks.</li><li>Check assumptions, edge cases, labelled diagrams and complexity/formulae where relevant.</li></ol></div><div class="task-actions" style="margin-top:16px"><select class="field-control" style="max-width:175px" data-topic-status="'+t.id+'">'+STATUSES.map(v=>'<option '+(v===st?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select><button class="btn" data-topic-note="'+t.id+'">Add note</button><button class="btn" data-topic-mistake="'+t.id+'">Log gap</button><button class="btn btn-primary" data-action="topic-revise" data-topic="'+t.id+'">Add to revision</button><button class="btn" data-action="topic-bookmark" data-topic="'+t.id+'">'+(state.bookmarks.includes('topic:'+t.id)?'★ Saved':'☆ Bookmark')+'</button></div></section><div class="section-heading"><div><h2>Related practice</h2><p>Curated course-aligned practice, not guaranteed exact PYQ matches.</p></div><button class="inline-link" data-go="#/pyqs?subject='+s.id+'">Question bank →</button></div><div class="grid grid-2">'+rel.map(q=>'<section class="panel"><div class="question-kind">'+esc(q.type)+' · '+esc(s.short)+'</div><h2 style="margin-top:10px">'+esc(q.q)+'</h2><button class="btn btn-sm" data-go="#/questions/'+q.id+'">Open question →</button></section>').join('')+'</div><div class="task-actions" style="justify-content:space-between;margin-top:17px">'+(prev?'<button class="btn" data-go="#/topics/'+prev.id+'">← Previous topic</button>':'<span></span>')+(next?'<button class="btn btn-primary" data-go="#/topics/'+next.id+'">Next topic →</button>':'<button class="btn" data-go="#/syllabus">Back to syllabus</button>')+'</div>';}
function questionBank(){return [...SHORT,...D.questions.map(q=>({...q,type:q.type==='MCQ'?'MCQ':q.type}))];}
function questionMarks(q){return q.marks||((q.type==='MCQ')?1:(q.type==='Short'?2:(q.type==='Long'?7:0)));}
function isSupplementary(q){const txt=(q.evidence||'').toLowerCase();return txt.includes('coa pyq collection')||txt.includes('supplementary')||txt.includes('other semester')||txt.includes('different code');}
const QUESTION_TOPIC_MAP={
'cn1':'CN-0-1','cn2':'CN-3-1','cn3':'CN-4-0','cn4':'CN-1-5','cn5':'CN-0-1','cn6':'CN-4-1',
'coa1':'COA-1-2','coa2':'COA-1-1','coa3':'COA-5-3','coa4':'COA-3-1','coa5':'COA-1-2','coa6':'COA-5-1',
'flat1':'FLAT-1-1','flat2':'FLAT-2-2','flat3':'FLAT-1-2','flat4':'FLAT-5-2','flat5':'FLAT-1-5','flat6':'FLAT-0-1',
'daa1':'DAA-1-1','daa2':'DAA-2-1','daa3':'DAA-3-0','daa4':'DAA-5-1','daa5':'DAA-1-1','daa6':'DAA-2-1',
'dbms1':'DBMS-3-0','dbms2':'DBMS-1-3','dbms3':'DBMS-1-1','dbms4':'DBMS-4-1','dbms5':'DBMS-1-3','dbms6':'DBMS-3-1',
'etc1':'ETC-4-0','etc2':'ETC-0-0','etc3':'ETC-5-1','etc4':'ETC-5-0','etc5':'ETC-4-0','etc6':'ETC-5-1',
'short-cn-1':'CN-1-1','short-cn-2':'CN-1-5','short-coa-1':'COA-2-1','short-coa-2':'COA-4-1',
'short-flat-1':'FLAT-1-1','short-flat-2':'FLAT-2-3','short-daa-1':'DAA-0-1','short-daa-2':'DAA-2-0',
'short-dbms-1':'DBMS-0-3','short-dbms-2':'DBMS-1-2','short-etc-1':'ETC-0-0','short-etc-2':'ETC-4-0'
};
function questionMeta(q){
 const t=topicById(QUESTION_TOPIC_MAP[q.id]||q.topicId),s=subj(q.s);
 return {topic:t||null,subject:s||null,unitIndex:t?t.unitIndex:null,unitKey:t?t.s+':'+t.unitIndex:'UNMAPPED',priority:q.priority||t?.priority||'Unrated',year:q.year||q.sourceYear||null,source:isSupplementary(q)?'Supplementary pattern':(q.sourceType||'Curated practice'),marks:questionMarks(q)};
}
function pyqsPage(){
 const qs=questionBank();
 const unitOptions=SUBJECTS.filter(s=>subjectFilter==='ALL'||s.id===subjectFilter).flatMap(s=>s.units.map((u,i)=>[s.id+':'+i,s.short+' · '+u.name]));
 const topicOptions=ALL_TOPICS.filter(t=>subjectFilter==='ALL'||t.s===subjectFilter);
 const years=[...new Set(qs.map(q=>questionMeta(q).year).filter(Boolean).map(String))].sort((a,b)=>Number(b)-Number(a));
 const arr=qs.filter(q=>{
  const m=questionMeta(q);
  return (subjectFilter==='ALL'||q.s===subjectFilter)
   &&(questionType==='ALL'||q.type===questionType)
   &&(!questionSearch||q.q.toLowerCase().includes(questionSearch.toLowerCase()))
   &&(pyqMarks==='ALL'||String(m.marks)===pyqMarks)
   &&(pyqPriority==='ALL'||m.priority===pyqPriority)
   &&(pyqUnit==='ALL'||m.unitKey===pyqUnit)
   &&(pyqTopic==='ALL'||(m.topic&&m.topic.id===pyqTopic))
   &&(pyqYear==='ALL'||(pyqYear==='UNVERIFIED'&&!m.year)||(String(m.year)===pyqYear))
   &&(pyqSource==='ALL'||m.source===pyqSource)
   &&(pyqCompletion==='ALL'||(pyqCompletion==='Saved'?state.bookmarks.includes(q.id):(state.questionAnswers[q.id]!==undefined&&state.questionAnswers[q.id]!==null)));
 });
 return heading('PYQ bank & question practice','Filter by subject, type, unit, topic, syllabus priority, marks and completion. Source year is only filterable when a question has verified paper metadata.','<button class="btn btn-primary" data-go="#/practice">Practice centre →</button>')+
 '<div class="filters-bar"><label class="search-box"><span>⌕</span><input class="search-input" id="question-search" type="search" value="'+esc(questionSearch)+'" placeholder="Search a topic or question" aria-label="Search questions"></label><div class="filter-pills">'+[['ALL','All types'],['MCQ','MCQ'],['Short','Short'],['Long','Long answer']].map(([v,l])=>'<button class="filter-pill '+(questionType===v?'active':'')+'" data-type-filter="'+v+'">'+l+'</button>').join('')+'</div></div>'+
 '<div class="grid grid-3" style="margin-bottom:10px">'+
 '<select class="field-control" style="max-width:100%" id="pyq-subject-filter" aria-label="Filter by subject">'+[['ALL','All subjects'],...SUBJECTS.map(s=>[s.id,s.short+' · '+s.name])].map(([v,l])=>'<option value="'+v+'" '+(subjectFilter===v?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>'+
 '<select class="field-control" id="pyq-unit-filter" aria-label="Filter by unit"><option value="ALL">All units</option>'+unitOptions.map(([v,l])=>'<option value="'+v+'" '+(pyqUnit===v?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>'+
 '<select class="field-control" id="pyq-topic-filter" aria-label="Filter by topic"><option value="ALL">All mapped topics</option>'+topicOptions.map(t=>'<option value="'+t.id+'" '+(pyqTopic===t.id?'selected':'')+'>'+esc(t.subject.short+' · '+t.name)+'</option>').join('')+'</select>'+
 '<select class="field-control" id="pyq-year-filter" aria-label="Filter by source year"><option value="ALL">All source years</option><option value="UNVERIFIED" '+(pyqYear==='UNVERIFIED'?'selected':'')+'>Year not verified</option>'+years.map(y=>'<option value="'+y+'" '+(pyqYear===y?'selected':'')+'>'+esc(y)+'</option>').join('')+'</select>'+
 '<select id="pyq-marks-filter" class="field-control" aria-label="Filter by marks"><option value="ALL">All marks</option>'+['1','2','5','7','10'].map(x=>'<option value="'+x+'" '+(pyqMarks===x?'selected':'')+'>'+x+' marks</option>').join('')+'</select>'+
 '<select class="field-control" id="pyq-priority-filter" aria-label="Filter by syllabus priority"><option value="ALL">All priorities</option>'+['High','Medium','Low','Unrated'].map(x=>'<option value="'+x+'" '+(pyqPriority===x?'selected':'')+'>'+x+' priority</option>').join('')+'</select>'+
 '<select class="field-control" id="pyq-source-filter" aria-label="Filter by source type"><option value="ALL">All source types</option>'+[['Curated practice','Curated practice'],['Supplementary pattern','Supplementary topic pattern']].map(([v,l])=>'<option value="'+v+'" '+(pyqSource===v?'selected':'')+'>'+l+'</option>').join('')+'</select>'+
 '<select id="pyq-status-filter" class="field-control" aria-label="Filter by completion"><option value="ALL">All completion states</option><option value="Saved" '+(pyqCompletion==='Saved'?'selected':'')+'>Bookmarked</option><option value="Attempted" '+(pyqCompletion==='Attempted'?'selected':'')+'>Attempted or revealed</option></select><div class="plan-date-bar" style="margin:0;padding:10px 12px"><strong>'+arr.length+' questions</strong><button class="inline-link" data-action="clear-pyq-filters">Clear filters</button></div></div>'+
 '<div class="grid grid-2">'+(arr.length?arr.map(q=>{const m=questionMeta(q);return '<section class="panel question-card"><div class="question-top"><span class="question-kind">'+esc(q.type)+' · '+esc(subj(q.s)?.short||q.s)+'</span>'+badge(m.source,m.source==='Supplementary pattern'?'amber':'blue')+'</div><div class="question-prompt">'+esc(q.q)+'</div><div class="topic-detail">'+badge(esc(subj(q.s)?.code||''))+' '+badge(m.marks+' marks','purple')+(m.unitIndex!==null?badge('Unit '+(m.unitIndex+1)):'')+(m.priority!=='Unrated'?priorityTag(m.priority):'')+(state.questionAnswers[q.id]!==undefined&&state.questionAnswers[q.id]!==null?badge('Attempted','green'):'')+'</div><p class="muted text-xs" style="line-height:1.65;margin-top:8px">'+(m.topic?'Mapped topic: '+esc(m.topic.name):'Topic mapping not available')+(m.year?' · Source year '+esc(m.year):' · Source year not verified')+'</p><div class="question-actions"><button class="btn btn-primary btn-sm" data-go="#/questions/'+q.id+'">Open & practise →</button><button class="btn btn-sm" data-bookmark="'+q.id+'">'+(state.bookmarks.includes(q.id)?'★ Saved':'☆ Save')+'</button></div></section>';}).join(''):'<div class="empty-state"><div class="empty-icon">⌕</div><strong>No questions match</strong>Broaden the search or clear filters.</div>')+'</div>'+
 '<section class="panel" style="margin-top:16px"><h2>Academic provenance</h2><p class="muted text-sm" style="line-height:1.75">The current bank combines curated syllabus-aligned questions with a few practice prompts based on themes in the uploaded COA material. A topic association is not a claim that the displayed wording is an original exam question. The uploaded paper bundle includes other-semester and different-course-code papers; those should be labelled by their actual paper metadata before being treated as current-semester PYQs.</p></section>';
}
function questionPage(id){const q=questionBank().find(x=>x.id===id);if(!q)return emptyRoute('Question not found','Choose a question from the bank.','#/pyqs');const s=subj(q.s),saved=state.questionAnswers[q.id],mcq=q.type==='MCQ',long=q.type==='Long';return heading('Question & solution',esc(s?.name||q.s)+' · '+q.type,'<button class="btn" data-go="#/pyqs">← Question bank</button>')+'<section class="panel"><div class="question-top"><div class="question-kind">'+esc(q.type)+' · '+esc(s?.code||q.s)+'</div>'+badge(questionMarks(q)+' marks','purple')+'</div><div class="question-prompt" style="font-size:18px">'+esc(q.q)+'</div>'+ (mcq?'<div class="options-list">'+q.o.map((o,i)=>'<button class="answer-option '+(saved!==undefined?(i===q.a?'correct':i===saved?'wrong':''):'')+'" '+(saved!==undefined?'disabled':'')+' data-answer-question="'+q.id+'" data-answer="'+i+'"><span class="option-letter">'+String.fromCharCode(65+i)+'</span><span>'+esc(o)+'</span></button>').join('')+'</div>'+(saved!==undefined?'<div class="answer-feedback"><strong>'+(saved===q.a?'Correct answer.':'Correct answer: '+esc(q.o[q.a]))+'</strong><br>'+esc(q.e||'')+'</div>':''):(long?'<button class="btn" data-action="reveal-question" data-question="'+q.id+'">'+(saved==='shown'?'Hide suggested structure':'Reveal answer structure')+'</button>'+(saved==='shown'?'<div class="answer-outline"><strong>Suggested answer structure</strong><ol>'+((q.outline||[]).map(x=>'<li>'+esc(x)+'</li>').join(''))+'</ol>'+(q.evidence?'<p class="muted text-xs">'+esc(q.evidence)+'</p>':'')+'</div>':''):'<button class="btn" data-action="reveal-question" data-question="'+q.id+'">'+(saved==='shown'?'Hide suggested answer':'Reveal suggested answer')+'</button>'+(saved==='shown'?'<div class="answer-outline">'+esc(q.a||'Define the term, explain its key property, then give an example.')+'</div>':'')))+'<div class="line"></div><div class="task-actions"><button class="btn" data-bookmark="'+q.id+'">'+(state.bookmarks.includes(q.id)?'★ Saved':'☆ Bookmark')+'</button><button class="btn" data-action="question-mistake" data-question="'+q.id+'">Log as mistake</button><a class="btn btn-quiet" target="_blank" rel="noopener" href="'+chatLink('Help me write a clear exam-ready answer to this BEU CSE Semester 4 question: '+q.q+' Explain assumptions and verify against standard course concepts.')+'">Study with ChatGPT ↗</a></div></section>'+(q.evidence?'<section class="panel" style="margin-top:12px"><h2>Question provenance</h2><p class="muted text-sm">'+esc(q.evidence)+'</p></section>':'');}
function practicePage(){return heading('Practice centre','Run a short MCQ set, focus on a single subject, or rehearse a written answer. Explanations and topic gaps should drive the next revision session.')+'<div class="grid grid-2"><section class="panel panel-elevated"><div class="eyebrow">QUICK RECALL</div><h2 style="font-size:22px">10 questions. Immediate feedback.</h2><p class="muted text-sm" style="line-height:1.8">The current timed mode covers the available curated MCQs. It is not an official BEU mock paper and cannot predict your exam score.</p><div class="line"></div><div class="field"><label for="quiz-subject">Choose a subject</label><select id="quiz-subject" class="field-control"><option value="ALL">All subjects</option>'+SUBJECTS.map(s=>'<option value="'+s.id+'">'+esc(s.short+' · '+s.name)+'</option>').join('')+'</select></div><div class="field" style="margin-top:12px"><label for="quiz-count">Question count</label><select id="quiz-count" class="field-control"><option>5</option><option selected>10</option><option>15</option><option>20</option></select></div><div class="task-actions" style="margin-top:17px"><button class="btn btn-primary" data-action="start-quiz">Start test →</button><button class="btn" data-go="#/pyqs">Browse question bank</button></div></section><section class="panel"><h2>Recent attempts</h2>'+(state.scores.length?state.scores.slice(-6).reverse().map(r=>'<div class="exam-row"><div class="exam-date-block"><strong>'+r.percent+'%</strong><small>SCORE</small></div><div class="exam-info"><div class="exam-title">'+esc(r.subject==='ALL'?'All subjects':subj(r.subject)?.short||r.subject)+'</div><div class="exam-code">'+dateLabel(r.date)+' · '+r.correct+'/'+r.total+' correct</div></div></div>').join(''):'<p class="muted text-sm">No attempts yet. Results will appear after your first test.</p>')+'</section></div><div class="section-heading"><div><h2>Other practice modes</h2><p>Each is a different way to build retrieval strength.</p></div></div><div class="grid grid-3"><section class="panel"><span class="badge badge-purple">Short answers</span><h2 style="margin-top:12px">Definitions drill</h2><p class="muted text-sm">Practise concise definitions and distinctions.</p><button class="btn" data-go="#/pyqs?type=Short">Open short-answer bank →</button></section><section class="panel"><span class="badge badge-blue">Written practice</span><h2 style="margin-top:12px">Long-answer rehearsal</h2><p class="muted text-sm">Reveal suggested structures, then compare your own answer.</p><button class="btn" data-action="show-long">Browse long answers →</button></section><section class="panel"><span class="badge badge-green">Weak topics</span><h2 style="margin-top:12px">Targeted review</h2><p class="muted text-sm">Review topics marked Needs revision or due for recall.</p><button class="btn" data-go="#/revision">Open revision hub →</button></section></div>';}
function savedResultPage(r){const items=Array.isArray(r.items)?r.items:[];const answers=r.answers||{};return heading('Test results','Saved attempt review. Your original selections are stored with this attempt.','<button class="btn" data-go="#/practice">Practice again</button>')+'<section class="panel" style="text-align:center;padding:30px"><div class="eyebrow">SAVED ATTEMPT · '+dateLabel(r.date)+'</div><div class="quiz-result-score" style="margin:15px 0">'+r.percent+'% <small>'+r.correct+'/'+r.total+'</small></div><p class="muted">'+esc(r.subject==='ALL'?'All subjects':subj(r.subject)?.name||r.subject)+' · '+(r.duration||0)+' minutes</p></section><div class="section-heading"><div><h2>Answer review</h2><p>Compare your response with the correct answer.</p></div></div>'+(items.length?items.map((q,i)=>{const ans=answers[q.id];return '<section class="panel question-card"><div class="question-top"><span class="question-kind">QUESTION '+(i+1)+'</span>'+badge(ans===q.a?'Correct':'Review',ans===q.a?'green':'red')+'</div><div class="question-prompt">'+esc(q.q)+'</div><div class="answer-feedback"><strong>Your answer: '+esc(typeof ans==='number'?(q.o||[])[ans]||'No answer':'No answer recorded')+'</strong><br><strong>Correct answer: '+esc((q.o||[])[q.a]||'Unavailable')+'</strong><br>'+esc(q.e||'')+'</div></section>';}).join(''):'<section class="panel"><p class="muted">This attempt was recorded before answer-level review was introduced. Its summary is preserved, but individual answers were not saved.</p></section>');}
function quizPage(){if(!quizState){const saved=state.scores.find(x=>x.id===route.param)||(route.param==='latest'?state.scores[state.scores.length-1]:null);if(route.page==='results'&&saved)return savedResultPage(saved);return practicePage();}if(quizState.done){const pct=Math.round(quizState.correct/quizState.items.length*100);return heading('Test results','Review every missed answer and use the gaps to guide revision.','<button class="btn" data-go="#/progress">See progress →</button>')+'<section class="panel" style="text-align:center;padding:clamp(22px,6vw,42px)"><div class="eyebrow">ATTEMPT COMPLETE</div><div class="quiz-result-score" style="margin:16px 0">'+pct+'% <small>'+quizState.correct+'/'+quizState.items.length+'</small></div><h2>'+(pct>=80?'Strong recall':pct>=60?'Good base—revise weak spots':'Use this as your revision map')+'</h2><p class="muted">This score applies only to this practice set; it is not a prediction of university marks.</p><div class="task-actions" style="justify-content:center;margin-top:16px"><button class="btn btn-primary" data-action="restart-quiz">Try again</button><button class="btn" data-action="end-quiz">Back to practice</button><button class="btn btn-quiet" data-go="#/revision">Review weak topics</button></div></section><div class="section-heading"><div><h2>Answer review</h2><p>All responses and explanations.</p></div></div>'+quizState.items.map((q,i)=>'<section class="panel question-card"><div class="question-top"><span class="question-kind">QUESTION '+(i+1)+'</span>'+badge(quizState.answers[q.id]===q.a?'Correct':'Review',quizState.answers[q.id]===q.a?'green':'red')+'</div><div class="question-prompt">'+esc(q.q)+'</div><div class="answer-feedback"><strong>Correct answer: '+esc(q.o[q.a])+'</strong><br>'+esc(q.e||'')+'</div>'+(quizState.answers[q.id]!==q.a?'<button class="btn btn-sm" data-question-mistake="'+q.id+'">Add mistake to revision</button>':'')+'</section>').join('');}
 const q=quizState.items[quizState.index];if(!q){quizState.done=true;return quizPage();}const answer=quizState.answers[q.id],chosen=answer!==undefined;
 return '<div class="quiz-stage">'+heading('Practice question','One at a time. Read the explanation before continuing.')+'<section class="panel"><div class="quiz-progress-head"><span>QUESTION '+(quizState.index+1)+' OF '+quizState.items.length+'</span><span>'+quizState.correct+' correct so far</span></div>'+meter((quizState.index+1)/quizState.items.length*100)+'<div class="question-kind" style="margin-top:22px">'+esc(subj(q.s)?.short||q.s)+' · MULTIPLE CHOICE</div><div class="quiz-question">'+esc(q.q)+'</div><div class="options-list">'+q.o.map((o,i)=>'<button class="answer-option '+(chosen?(i===q.a?'correct':i===answer?'wrong':''):'')+'" '+(chosen?'disabled':'')+' data-quiz-answer="'+i+'"><span class="option-letter">'+String.fromCharCode(65+i)+'</span><span>'+esc(o)+'</span></button>').join('')+'</div>'+(chosen?'<div class="answer-feedback">'+(answer===q.a?'<strong>Correct.</strong>':'<strong>Not quite. Correct answer: '+esc(q.o[q.a])+'.</strong> ')+' '+esc(q.e||'')+'</div>':'')+'<div class="task-actions" style="justify-content:space-between;margin-top:18px"><button class="btn btn-quiet" data-action="end-quiz">Exit test</button>'+(chosen?'<button class="btn btn-primary" data-action="next-quiz">'+(quizState.index===quizState.items.length-1?'See results':'Next question →')+'</button>':'<span class="muted text-xs">Choose one answer to continue.</span>')+'</div></section></div>';}
function noteModal(mode,topicId='',recordId=''){const isMistake=mode==='mistake',list=isMistake?state.mistakes:state.notes,existing=list.find(n=>n.id===recordId),topic=topicById(topicId||existing?.topic);return '<div class="modal-backdrop" data-dismiss-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="note-modal-title"><div class="eyebrow">'+(isMistake?'MISTAKE LOG':'PERSONAL STUDY NOTES')+'</div><h2 id="note-modal-title">'+(existing?'Edit ': 'Add ')+(isMistake?'mistake':'study note')+'</h2><p class="modal-intro">'+(topic?'Topic: '+esc(topic.name)+'. ':'')+'Saved locally in this browser.</p><form id="note-form" class="form-grid" data-mode="'+mode+'" data-topic="'+esc(topicId||existing?.topic||'')+'" data-record="'+esc(recordId)+'"><div class="field"><label for="note-title">Title</label><input class="field-control" id="note-title" name="title" maxlength="120" required value="'+esc(existing?.title||topic?.name||'')+'" placeholder="A concise reminder"></div><div class="field"><label for="note-body">'+(isMistake?'What was missed, and what is the correction?':'Your note')+'</label><textarea id="note-body" name="body" class="field-control" required maxlength="10000" placeholder="Write the method, formula, correction or recall cue">'+esc(existing?.body||'')+'</textarea></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">Save '+(isMistake?'mistake':'note')+'</button></div></form></section></div>';}
function notesPage(){const n=state.notes,m=state.mistakes;return heading('Notes & mistakes','Turn definitions, formulas and errors into a personal revision resource.','<button class="btn" data-action="new-mistake">+ Log mistake</button><button class="btn btn-primary" data-action="new-note">+ Add note</button>')+'<div class="tabs"><button class="tab-button '+(notesTab==='notes'?'active':'')+'" data-note-tab="notes">Study notes ('+n.length+')</button><button class="tab-button '+(notesTab==='mistakes'?'active':'')+'" data-note-tab="mistakes">Mistakes ('+m.length+')</button><button class="tab-button '+(notesTab==='sessions'?'active':'')+'" data-note-tab="sessions">Study time ('+state.sessions.length+')</button></div><div id="notes-view" style="margin-top:15px">'+notesListMarkup(notesTab)+'</div>';}
function notesListMarkup(which){let a=which==='mistakes'?state.mistakes:which==='sessions'?state.sessions:state.notes;if(!a.length)return '<div class="empty-state"><div class="empty-icon">✎</div><strong>'+(which==='mistakes'?'No mistakes logged yet':which==='sessions'?'No study sessions logged':'Your revision space starts here')+'</strong>'+(which==='mistakes'?'Record the exact gap and the correction.':which==='sessions'?'Log focused minutes to understand your consistency.':'Save definitions, formulas and answer structures here.')+'<button class="btn btn-primary" style="margin-top:13px" data-action="'+(which==='mistakes'?'new-mistake':which==='sessions'?'log-session':'new-note')+'">'+(which==='mistakes'?'Log first mistake':which==='sessions'?'Log study time':'Add first note')+'</button></div>';
 if(which==='sessions')return '<div class="grid grid-2">'+a.slice().reverse().map(x=>'<article class="note-card"><div class="question-top"><div class="note-card-title">'+esc(x.minutes)+' minutes of study</div>'+badge(dateLabel(x.date),'green')+'</div><p>'+esc(x.note||'Focused study session')+'</p><div class="note-card-meta">'+esc(x.subject==='ALL'?'General':subj(x.subject)?.short||x.subject)+'</div><button class="btn btn-sm" data-delete-session="'+x.id+'">Delete</button></article>').join('')+'</div>';
 return '<div class="grid grid-2">'+a.slice().sort((x,y)=>(y.createdAt||'').localeCompare(x.createdAt||'')).map(x=>'<article class="note-card"><div class="question-top"><div class="note-card-title">'+esc(x.title)+'</div>'+badge(which==='mistakes'?'Mistake':'Note',which==='mistakes'?'red':'purple')+'</div><p>'+esc(x.body)+'</p><div class="note-card-meta">'+dateLabel((x.createdAt||today()).slice(0,10))+(x.topic?' · '+esc(topicById(x.topic)?.subject.short||'Linked topic'):'')+'</div><div class="task-actions"><button class="btn btn-sm" data-edit-record="'+which+':'+x.id+'">Edit</button><button class="btn btn-sm btn-quiet" data-delete-record="'+which+':'+x.id+'">Delete</button></div></article>').join('')+'</div>';}
function plannerPage(){const tasks=planTasks(),done=tasks.filter(t=>state.dayDone[t.id]).length,e=activeExam(),eve=new Date(e.date+'T12:00:00');eve.setDate(eve.getDate()-1);return heading('Study planner','A daily plan shaped around your study hours and the exam sequence. The day before a paper receives focused revision.','<button class="btn" data-action="regenerate-plan">↻ Refresh plan</button>')+'<div class="plan-date-bar"><div><strong>Today · '+dateLabel(today())+'</strong><small>'+state.prefs.hours+' hours/day · '+esc(state.prefs.mode)+' strategy</small></div><div class="actions">'+badge(done+'/'+tasks.length+' completed',done===tasks.length?'green':'purple')+((today()===e.date||eve.toISOString().slice(0,10)===today())?badge('Exam focus day','amber'):'')+'</div></div><div class="section-grid"><section class="panel"><div class="section-heading" style="margin-top:0"><div><h2>Today’s study blocks</h2><p>Mark complete after doing the work.</p></div></div><div class="progress-meta"><span>'+done+' blocks complete</span><span>'+Math.round(done/Math.max(1,tasks.length)*100)+'%</span></div>'+meter(done/Math.max(1,tasks.length)*100,'mint')+tasks.map(taskCard).join('')+'<div class="task-actions" style="margin-top:13px"><button class="btn btn-primary" data-action="log-session">Log time</button><button class="btn btn-quiet" data-go="#/revision">Review mistakes</button></div></section><div class="content-stack"><section class="panel"><h2>Next exam</h2>'+examRow(e)+'<p class="muted text-sm" style="line-height:1.75;margin-top:12px">Prioritise closed-book recall, answer structures, diagrams/numericals and your error list before a paper.</p></section><section class="panel"><h2>Exam timetable</h2>'+EXAMS.map(examRow).join('')+'</section></div></div><div class="section-heading"><div><h2>A productive study block</h2><p>Move from understanding to reproducing an answer.</p></div></div><div class="grid grid-3"><section class="panel"><span class="badge badge-purple">01 · Learn</span><h2 style="margin-top:10px">Concept pass</h2><p class="muted text-sm">Write the definition and draw the key diagram or formula map.</p></section><section class="panel"><span class="badge badge-blue">02 · Practise</span><h2 style="margin-top:10px">Answer pass</h2><p class="muted text-sm">Solve a numerical or draft a 5–10 mark answer.</p></section><section class="panel"><span class="badge badge-green">03 · Recall</span><h2 style="margin-top:10px">Memory pass</h2><p class="muted text-sm">Close notes and add anything forgotten to the mistake list.</p></section></div>';}
function revisionPage(){const now=ALL_TOPICS.filter(t=>topicStatus(t)==='Needs revision'||topicStatus(t)==='Learning'),due=ALL_TOPICS.filter(t=>{const x=state.flashcards[t.id];return x&&x.due<=today();}),items=due.length?due:now;const t=items.length?items[Math.min(revisionIndex,items.length-1)]:null;return heading('Revision hub','Prioritise topics that need work and revisit them using active recall. A topic is not a memorised fact just because it looks familiar.')+'<div class="grid grid-3">'+metric('↻',items.length,'Topics in the queue','Needs revision or due for recall')+metric('✎',state.mistakes.length,'Logged mistakes','Specific gaps worth revisiting','amber')+metric('★',state.bookmarks.length,'Saved items','Topics and questions','blue')+'</div><div class="section-heading"><div><h2>Active recall cards</h2><p>Try to answer before revealing the topic prompt.</p></div></div>'+(t?'<section class="panel panel-elevated"><div class="question-top"><div class="eyebrow">'+esc(t.subject.short)+' · '+(revisionIndex+1)+' OF '+items.length+'</div>'+priorityTag(t.priority)+'</div><h2 style="font-size:22px;margin:12px 0 20px">'+esc(t.name)+'</h2><p class="muted text-sm">Without notes, write the definition, steps and one exam-style example.</p><div class="task-actions" style="margin-top:18px"><button class="btn" data-action="flip-revision">Reveal study cues</button><button class="btn" data-action="revision-prev">← Previous</button><button class="btn" data-action="revision-next">Next →</button></div><div id="revision-cues" hidden class="answer-outline"><strong>Recall checklist</strong><ol><li>Define all central terms.</li><li>State assumptions or conditions.</li><li>Show the method, theorem or diagram in ordered steps.</li><li>Work a representative example.</li><li>Close the answer with complexity, limitation or comparison if relevant.</li></ol></div><div class="task-actions"><select class="field-control" style="max-width:185px" data-topic-status="'+t.id+'">'+STATUSES.map(v=>'<option '+(v===topicStatus(t)?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select><button class="btn btn-primary" data-action="reviewed" data-topic="'+t.id+'">Reviewed — schedule again</button><button class="btn" data-topic-note="'+t.id+'">Add note</button></div></section>':'<div class="empty-state"><div class="empty-icon">✓</div><strong>No topics in the revision queue</strong>Mark a topic “Needs revision” from the syllabus when recall is weak.</div>')+'<div class="section-heading"><div><h2>Mistakes to revisit</h2><p>Review the explanation and attempt the question again.</p></div><button class="inline-link" data-go="#/notes">All notes →</button></div>'+notesListMarkup('mistakes');}
function progressPage(){const p=state.scores.slice(-10),minutes=state.sessions.reduce((n,s)=>n+(Number(s.minutes)||0),0),subjectMetrics=SUBJECTS.map(s=>{const qs=questionBank().filter(q=>q.s===s.id&&state.questionAnswers[q.id]!==undefined);const correct=qs.filter(q=>q.type==='MCQ'&&state.questionAnswers[q.id]===q.a).length;return {s,qs,correct,percent:qs.length?Math.round(correct/qs.length*100):0};});return heading('My progress','Evidence of preparation: topic states, actual quiz responses and logged study time. These measurements do not predict final marks.')+'<div class="grid grid-4">'+metric('◉',overallProgress()+'%','Weighted topic mastery','Topic status estimate')+metric('✓',ALL_TOPICS.filter(recalled).length+'/'+ALL_TOPICS.length,'Topics recalled','Recall passed or exam-ready','mint')+metric('◷',Math.round(minutes/60*10)/10+'h','Logged study time','Only sessions you recorded','blue')+metric('✎',p.length,'Recent test attempts','MCQ scores','amber')+'</div><div class="section-heading"><div><h2>Topic coverage by subject</h2><p>Weighted state progress is not a measured probability of passing.</p></div><button class="inline-link" data-go="#/subjects">Subjects →</button></div><section class="panel">'+SUBJECTS.map(s=>'<div style="margin-bottom:15px"><div class="progress-meta"><span>'+esc(s.name)+'</span><strong>'+subjectProgress(s)+'%</strong></div>'+meter(subjectProgress(s))+'</div>').join('')+'</section><div class="section-heading"><div><h2>Practice accuracy by subject</h2><p>Calculated from questions actually answered and stored.</p></div><button class="inline-link" data-go="#/practice">Practice →</button></div><div class="grid grid-3">'+subjectMetrics.map(x=>'<section class="panel"><h2>'+esc(x.s.short)+'</h2><div class="metric-value">'+(x.qs.length?x.percent+'%':'—')+'</div><p class="muted text-sm">'+x.correct+' correct out of '+x.qs.filter(q=>q.type==='MCQ').length+' answered MCQs</p>'+meter(x.percent)+'</section>').join('')+'</div><div class="section-heading"><div><h2>Recent quiz attempts</h2><p>Keep practicing to build a useful evidence trail.</p></div></div><section class="panel">'+(p.length?p.slice().reverse().map(x=>'<div class="exam-row"><div class="exam-date-block"><strong>'+x.percent+'%</strong><small>SCORE</small></div><div class="exam-info"><div class="exam-title">'+esc(x.subject==='ALL'?'Mixed subjects':subj(x.subject)?.short||x.subject)+'</div><div class="exam-code">'+dateLabel(x.date)+' · '+x.correct+'/'+x.total+' correct</div></div></div>').join(''):'<p class="muted text-sm">No quiz results yet.</p>')+'</section>';}
function examsPage(){return heading('Exam calendar','Use the paper order to plan focus. Dates and 2–5 PM time are transcribed from the exam routine you supplied.','<button class="btn" data-go="#/planner">Study plan →</button>')+'<section class="panel"><div class="eyebrow">OCTOBER – NOVEMBER 2026</div>'+EXAMS.map(e=>examRow(e)+'<div class="exam-checklist">'+['Review high-priority syllabus topics','Attempt representative questions','Review mistakes and formulas','Prepare required stationery and exam details'].map((x,i)=>'<label class="mini-list-item" style="padding:5px 0"><input type="checkbox" data-exam-check="'+e.id+':'+i+'" '+(state.examChecks[e.id+':'+i]?'checked':'')+'> '+x+'</label>').join('')+'</div>').join('<div class="line"></div>')+'</section><section class="panel" style="margin-top:13px"><h2>After a paper</h2><p class="muted text-sm">Once an exam date passes, the dashboard moves its countdown to the next scheduled subject. Confirm later notices from your college/university because the tracker cannot detect schedule changes automatically.</p></section>';}
function savedPage(){const saved=state.bookmarks.map(id=>{if(id.startsWith('topic:'))return {kind:'Topic',id:id.slice(6),name:topicById(id.slice(6))?.name,go:'#/topics/'+id.slice(6)};const q=questionBank().find(q=>q.id===id);return {kind:'Question',id,name:q?.q,go:'#/questions/'+id};}).filter(x=>x.name);return heading('Saved items','Your bookmarks for topics and questions. Search the academic library or jump straight back into study.')+(saved.length?'<div class="grid grid-2">'+saved.map(x=>'<section class="panel"><div class="question-top"><span class="badge badge-purple">'+x.kind+'</span><button class="btn btn-sm btn-quiet" data-unsave="'+esc(x.id)+'">Remove ★</button></div><h2 style="margin-top:12px">'+esc(x.name)+'</h2><button class="btn btn-primary" data-go="'+x.go+'">Open →</button></section>').join('')+'</div>':'<div class="empty-state"><div class="empty-icon">★</div><strong>Nothing saved yet</strong>Bookmark topics and questions to gather your personal revision list.<button class="btn btn-primary" style="margin-top:12px" data-go="#/pyqs">Browse questions</button></div>')+'<div class="section-heading"><div><h2>Notes</h2><p>Study notes are managed separately.</p></div><button class="inline-link" data-go="#/notes">Open notes →</button></div>';}
function resourcesPage(){return heading('Study resources','Keep your syllabus, question-paper PDFs and personal references available on this device. PDF storage is separate from small progress records.','<button class="btn" data-go="#/settings">Storage & backup</button>')+'<div class="grid grid-2"><section class="panel panel-elevated"><div class="eyebrow">YOUR REFERENCE LIBRARY</div><h2 style="font-size:22px">Syllabus & PYQ PDFs</h2><p class="muted" style="line-height:1.8">Add the syllabus compilation, exam routine, previous papers and class notes. Files are saved in this browser, not uploaded to a server.</p><div class="line"></div><label class="btn btn-primary" for="pdf-upload">＋ Add PDF files</label><input id="pdf-upload" type="file" accept="application/pdf,.pdf" multiple hidden><p class="muted text-xs" style="margin-top:10px">PDF only. Keep an original copy elsewhere. Browser storage may be removed when site data is cleared.</p><div id="pdf-list" style="margin-top:15px">Loading local documents…</div></section><section class="panel"><h2>Study with ChatGPT</h2><p class="muted text-sm" style="line-height:1.8">Ask for an explanation on one named syllabus topic, then compare it with your provided course material.</p><div class="form-grid"><div class="field"><label for="chat-subject">Subject</label><select id="chat-subject" class="field-control">'+SUBJECTS.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'</select></div><div class="field"><label for="chat-topic">Topic or question</label><input id="chat-topic" class="field-control" placeholder="e.g. TCP congestion control"></div><button class="btn btn-primary" data-action="chat-topic">Open study prompt ↗</button><a class="btn" href="https://beu-bih.ac.in/" target="_blank" rel="noopener">Official BEU website ↗</a></div></section></div><div class="section-heading"><div><h2>Reference workflows</h2><p>Use the original paper when validating question provenance.</p></div></div><div class="grid grid-3"><section class="panel resource-card"><div class="resource-type">SYLLABUS</div><h3>Unit-wise syllabus</h3><p>Open each subject and mark each concept as learned, practised or exam-ready.</p><button class="btn" data-go="#/syllabus">Open checklist →</button></section><section class="panel resource-card"><div class="resource-type">PYQ BANK</div><h3>Question practice</h3><p>Curated MCQs, definitions and long-answer outlines; not a complete verbatim archive of every PDF question.</p><button class="btn" data-go="#/pyqs">Open bank →</button></section><section class="panel resource-card"><div class="resource-type">REVISION</div><h3>Personal notes</h3><p>Collect definitions, formulas, common mistakes and short answer cues.</p><button class="btn" data-go="#/notes">Open notes →</button></section></div>'; }
function settingsPage(){return heading('Profile & settings','Personalize your study routine, appearance and privacy settings. Your academic records stay in this browser unless you export a backup.')+'<div class="section-grid"><div class="content-stack"><section class="panel"><h2>Study routine</h2><form id="settings-form" class="form-grid"><div class="field"><label for="setting-name">Name (optional)</label><input id="setting-name" name="name" class="field-control" maxlength="70" value="'+esc(state.prefs.name)+'" placeholder="Name shown on dashboard"></div><div class="field"><label for="setting-hours">Study hours per day</label><select id="setting-hours" name="hours" class="field-control">'+[4,6,8,12].map(h=>'<option value="'+h+'" '+(Number(state.prefs.hours)===h?'selected':'')+'>'+h+' hours per day</option>').join('')+'</select></div><div class="field"><label for="setting-mode">Study strategy</label><select id="setting-mode" name="mode" class="field-control">'+[['Balanced','Balanced — concepts, practice and recall'],['Marks-focused','Marks-focused — priority-first'],['Crash course','Crash course — urgent revision']].map(([v,l])=>'<option value="'+v+'" '+(state.prefs.mode===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div><div class="field"><label for="setting-theme">Appearance</label><select id="setting-theme" name="theme" class="field-control"><option value="light" '+(state.prefs.theme==='light'?'selected':'')+'>Light</option><option value="dark" '+(state.prefs.theme==='dark'?'selected':'')+'>Dark (preview not enabled yet)</option></select><small>Light appearance follows your selected product reference. Dark preference is retained but this release remains light-first.</small></div><div class="field"><label for="setting-language">Language</label><select id="setting-language" name="language" class="field-control"><option value="en">English</option><option value="hi" disabled>Hindi explanations — planned</option></select></div><button class="btn btn-primary" type="submit">Save preferences</button></form></section><section class="panel"><h2>Local data backup</h2><p class="muted text-sm" style="line-height:1.8">Export your topic progress, preferences, notes, mistakes and results before changing devices or clearing browser data. PDF files must be kept/downloaded separately.</p><div class="task-actions"><button class="btn btn-primary" data-action="export-backup">Export JSON backup ↓</button><label class="btn" for="backup-import">Import backup ↑</label><input id="backup-import" type="file" accept="application/json,.json" hidden></div><div class="line"></div><button class="btn btn-danger" data-action="reset-progress">Reset local study progress</button><p class="muted text-xs">Reset permanently clears saved browser data for this app. Export first; this cannot be undone.</p></section></div><div class="content-stack"><section class="panel"><h2>Privacy & storage</h2><div class="mini-list"><div class="mini-list-item"><span class="mini-dot"></span>Progress is saved with localStorage.</div><div class="mini-list-item"><span class="mini-dot"></span>PDFs are kept in browser IndexedDB storage.</div><div class="mini-list-item"><span class="mini-dot"></span>No login or backend account is configured.</div><div class="mini-list-item"><span class="mini-dot"></span>Browser clearing/site data reset may remove this data.</div></div><div class="line"></div><div id="storage-status" class="muted text-sm">Checking local reference storage…</div></section><section class="panel"><h2>Install BEU Exam Prep</h2><p class="muted text-sm" style="line-height:1.8">Install from the browser menu or use the install icon at the top when available. The app shell can cache core pages; files and recently opened pages may still need a first online load.</p><button class="btn" data-action="install-prompt">Install app ↗</button></section><section class="panel"><h2>Product status</h2><p class="muted text-sm" style="line-height:1.8">This is a student-only, local-first PWA build. Shared accounts, cross-device sync, notifications, and multi-role content administration are not part of this release.</p></section></div></div>';}
function welcomePage(){return '<div class="quiz-stage"><section class="hero-card"><div class="hero-eyebrow">BEU EXAM PREP</div><h1 class="hero-title">Your next exam, made manageable.</h1><p class="hero-description">A personal study workspace for the BEU B.Tech CSE Semester 4 exam sequence: syllabus, planned study blocks, PYQ-style practice, revision and progress.</p><div class="hero-actions"><button class="btn btn-primary" data-go="#/onboarding">Set up my study plan →</button><button class="btn" data-action="explore-guest">Explore as guest</button></div></section><div class="grid grid-3"><section class="panel"><div class="metric-icon">▤</div><h2 style="margin-top:12px">Know your syllabus</h2><p class="muted text-sm">Six theory subjects arranged into units and topic checkpoints.</p></section><section class="panel"><div class="metric-icon blue">◷</div><h2 style="margin-top:12px">Choose a realistic plan</h2><p class="muted text-sm">Set your available hours and focus style; refresh the plan as your day changes.</p></section><section class="panel"><div class="metric-icon amber">✓</div><h2 style="margin-top:12px">Measure actual recall</h2><p class="muted text-sm">Track questions answered, topic status and mistakes—not unsupported predicted marks.</p></section></div><p class="muted text-xs" style="margin-top:17px">No account required. Your progress is stored locally on this device.</p></div>';}
function onboardingPage(){return '<div class="quiz-stage">'+heading('Personalize your plan','Set your study target. You can change all preferences later in Settings.')+'<section class="panel"><div class="eyebrow">STEP 1 OF 2 · YOUR DAILY CAPACITY</div><h2 style="font-size:23px">How much time can you study most days?</h2><p class="muted text-sm">Choose a repeatable target, not a one-day maximum.</p><div class="choice-grid" style="margin-top:14px">'+[4,6,8,12].map(h=>'<button class="choice-card '+(Number(onboardingDraft.hours)===h?'selected':'')+'" data-onboard-hours="'+h+'"><strong>'+h+' hours</strong><small>'+(h===4?'A compact daily routine':h===6?'A balanced preparation pace':h===8?'An intensive study day':'A crash-course target')+'</small></button>').join('')+'</div><div class="line"></div><div class="eyebrow">STEP 2 OF 2 · YOUR STUDY STYLE</div><h2>What is your immediate priority?</h2><div class="choice-grid" style="margin-top:14px">'+[['Balanced','Concepts, practice and recall'],['Marks-focused','Priority-first revision and answer practice'],['Crash course','Urgent preparation; focus on essentials']].map(([v,d])=>'<button class="choice-card '+(onboardingDraft.mode===v?'selected':'')+'" data-onboard-mode="'+v+'"><strong>'+v+'</strong><small>'+d+'</small></button>').join('')+'</div><div class="field" style="margin-top:15px"><label for="onboard-name">Name (optional)</label><input class="field-control" id="onboard-name" maxlength="70" placeholder="How should the dashboard greet you?" value="'+esc(onboardingDraft.name)+'"></div><div class="modal-actions"><button class="btn" data-action="explore-guest">Skip setup</button><button class="btn btn-primary" data-action="finish-onboarding">Build my study desk →</button></div><p class="modal-note">Your choices are stored on this device. Guest exploration does not create an online account.</p></section></div>';}
function emptyRoute(title,desc,go){return '<div class="empty-state"><div class="empty-icon">⌕</div><strong>'+esc(title)+'</strong>'+esc(desc)+'<button class="btn btn-primary" style="margin-top:13px" data-go="'+go+'">Continue →</button></div>';}
function getPdfDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB unavailable'));return;}const request=indexedDB.open('beu-exam-prep-pdfs',1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('pdfs'))db.createObjectStore('pdfs',{keyPath:'id',autoIncrement:true});};request.onsuccess=()=>{pdfDb=request.result;resolve(pdfDb);};request.onerror=()=>reject(request.error);});}
async function listPdfs(){const out=$('#pdf-list');if(!out)return;try{const db=await getPdfDB(),items=await new Promise((resolve,reject)=>{const r=db.transaction('pdfs').objectStore('pdfs').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});$('#storage-status')&&($('#storage-status').textContent=items.length+' PDF reference(s) stored in this browser.');out.innerHTML=items.length?'<div class="mini-list">'+items.map(f=>'<div class="task-row"><div class="metric-icon">▤</div><div class="task-content"><div class="task-title">'+esc(f.name)+'</div><div class="task-meta">'+(f.size/1024/1024).toFixed(2)+' MB · Added '+dateLabel(f.added)+'</div><div class="task-actions"><button class="btn btn-sm btn-primary" data-pdf-open="'+f.id+'">Open PDF</button><button class="btn btn-sm" data-pdf-download="'+f.id+'">Download</button><button class="btn btn-sm btn-danger" data-pdf-delete="'+f.id+'">Delete</button></div></div></div>').join('')+'</div>':'<div class="empty-state"><div class="empty-icon">▤</div><strong>No PDFs added yet</strong>Add syllabus or PYQ PDFs to create your local reference shelf.</div>';}catch(e){out.textContent='This browser could not open local PDF storage. Your study progress is unaffected.';}}
async function pdfRecord(id){const db=await getPdfDB();return new Promise((resolve,reject)=>{const r=db.transaction('pdfs').objectStore('pdfs').get(Number(id));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function uploadPdfs(files){const pdfs=Array.from(files||[]);if(!pdfs.length)return;const invalid=pdfs.filter(f=>f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf'));if(invalid.length){toast('Only PDF files can be added.');return;}try{const db=await getPdfDB();for(const f of pdfs){await new Promise((resolve,reject)=>{const r=db.transaction('pdfs','readwrite').objectStore('pdfs').add({name:f.name,size:f.size,added:today(),blob:f});r.onsuccess=resolve;r.onerror=()=>reject(r.error);});}toast(pdfs.length+' PDF file(s) saved on this device.');await listPdfs();}catch(e){toast('PDF storage was unavailable or full. Keep your original files in another location.');}}
function exportBackup(){const payload={product:'BEU Exam Prep',schemaVersion:1,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='beu-exam-prep-backup-'+today()+'.json';a.click();URL.revokeObjectURL(url);toast('Study data backup exported. PDF files are separate.');}
async function importBackup(file){try{const obj=JSON.parse(await file.text()),v=obj.state||obj;if(!v||v.version!==1||!v.prefs||!v.topics)throw new Error('The selected file is not a compatible BEU Exam Prep backup.');if(!confirm('Import this backup and replace the current study data on this device? Export your current data first if you need to keep both.'))return;state={...BASE(),...v,prefs:{...BASE().prefs,...v.prefs}};save();render();toast('Backup imported.');}catch(e){toast(e.message||'Could not read this backup.');}}
function installNav(){
 const desktop={dashboard:'#/dashboard',subjects:'#/subjects',subject:'#/subjects',topic:'#/subjects',syllabus:'#/syllabus',planner:'#/planner',pyqs:'#/pyqs',question:'#/pyqs',practice:'#/practice',results:'#/practice',revision:'#/revision',resources:'#/resources',exams:'#/exams',progress:'#/progress',saved:'#/saved',notes:'#/notes',settings:'#/settings'};
 const mobile={dashboard:'#/dashboard',subjects:'#/subjects',subject:'#/subjects',topic:'#/subjects',syllabus:'#/subjects',planner:'#/planner',pyqs:'#/pyqs',question:'#/pyqs',practice:'#/practice',results:'#/practice'};
 $$('.primary-nav [data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===desktop[route.page]));
 $$('.mobile-nav button[data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===mobile[route.page]));
 const meta=({dashboard:['Workspace','Home'],subjects:['Study','My subjects'],subject:['Study','Subject overview'],topic:['Study','Topic learning'],syllabus:['Study','Syllabus tracker'],planner:['Plan','Study planner'],pyqs:['Practice','PYQ bank'],question:['Practice','Question & solution'],practice:['Practice','Practice centre'],results:['Practice','Test results'],revision:['Revision','Revision hub'],resources:['Library','Study resources'],exams:['Plan','Exam calendar'],progress:['Insights','My progress'],saved:['Library','Saved items'],notes:['Revision','Notes & mistakes'],settings:['Account','Profile & settings'],welcome:['Welcome','Welcome'],onboarding:['Welcome','Setup']})[route.page]||['Workspace','Home'];
 $('#crumb-parent').textContent=meta[0];$('#crumb-current').textContent=meta[1];
 $('#avatar-initials').textContent=(state.prefs.name||'S').trim().slice(0,1).toUpperCase();
 if($('#install-button'))$('#install-button').hidden=!installPrompt;
}
function render(){if(location.hash!==lastFilterHash){const qp=new URLSearchParams((location.hash.split('?')[1]||''));if(qp.get('subject'))subjectFilter=qp.get('subject');if(qp.get('type'))questionType=qp.get('type');lastFilterHash=location.hash;}route=parseRoute(location.hash);if(!state.onboarded&&route.page==='dashboard')route.page='welcome';document.documentElement.dataset.theme=state.prefs.theme==='dark'?'dark':'light';if(route.page==='subject')root.innerHTML=subjectDetailPage(route.param);else if(route.page==='topic')root.innerHTML=topicPage(route.param);else {const fn={dashboard:dashboardPage,subjects:subjectsPage,syllabus:syllabusPage,planner:plannerPage,pyqs:pyqsPage,question:()=>questionPage(route.param),practice:practicePage,results:()=>quizPage(),revision:revisionPage,resources:resourcesPage,exams:examsPage,progress:progressPage,saved:savedPage,notes:notesPage,settings:settingsPage,welcome:welcomePage,onboarding:onboardingPage};root.innerHTML=(fn[route.page]||dashboardPage)();}installNav();if(route.page==='resources')listPdfs();if(route.page==='settings')listPdfs();if(route.page==='revision'&&$('#revision-cues'))$('#revision-cues').hidden=true;root.focus({preventScroll:true});}
function go(hash){if(!hash.startsWith('#'))hash='#/'+hash.replace(/^\/?/,'');if(location.hash===hash)render();else location.hash=hash;moreOpen=false;closeMore();}
function closeMore(){const m=$('#more-sheet');if(m)m.remove();moreOpen=false;}
function openMore(){closeMore();const m=document.createElement('div');m.id='more-sheet';m.className='more-sheet';m.setAttribute('aria-label','More destinations');const links=[['Revision hub','revision'],['Resources & PDFs','resources'],['Exam calendar','exams'],['My progress','progress'],['Saved & bookmarks','saved'],['Notes & mistakes','notes'],['Profile & settings','settings']];m.innerHTML=links.map(([l,p])=>'<button data-go="#/'+p+'">'+l+' →</button>').join('');document.body.appendChild(m);moreOpen=true;}
function showModal(html){$('#modal-root').innerHTML=html;}
function hideModal(){$('#modal-root').innerHTML='';}
function topicStatusSet(id,status){const t=topicById(id);if(!t)return;state.topics[id]={...(state.topics[id]||{}),status,updated:today()};if(status==='Needs revision'){state.flashcards[id]={due:today(),interval:1};}save();render();toast('Topic status saved.');}
function addMistake(questionId='',topicId=''){const q=questionBank().find(x=>x.id===questionId);showModal(noteModal('mistake',topicId||q?.id&&''||'', ''));}
function newSession(){showModal('<div class="modal-backdrop" data-dismiss-modal><section class="modal" role="dialog" aria-modal="true"><div class="eyebrow">STUDY LOG</div><h2>Log a focused session</h2><p class="modal-intro">Record actual study time, not intended time.</p><form id="session-form" class="form-grid"><div class="field"><label for="session-minutes">Minutes</label><input id="session-minutes" name="minutes" class="field-control" type="number" min="5" max="720" step="5" value="45" required></div><div class="field"><label for="session-subject">Subject</label><select name="subject" id="session-subject" class="field-control"><option value="ALL">General study</option>'+SUBJECTS.map(s=>'<option value="'+s.id+'">'+esc(s.short)+'</option>').join('')+'</select></div><div class="field"><label for="session-note">What did you study?</label><input id="session-note" name="note" class="field-control" maxlength="300" placeholder="Topic, practice set or review"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save session</button></div></form></section></div>');}
function startQuiz(){let s=$('#quiz-subject')?.value||'ALL',n=Number($('#quiz-count')?.value||10),all=D.questions.filter(q=>q.type==='MCQ'&&(s==='ALL'||q.s===s));if(!all.length){toast('No MCQs found for this subject.');return;}const shuffled=all.slice().sort(()=>Math.random()-.5).slice(0,Math.min(n,all.length));quizState={subject:s,items:shuffled,index:0,answers:{},correct:0,done:false,started:Date.now()};go('#/practice');render();}
function finishQuiz(){if(!quizState)return;quizState.done=true;const total=quizState.items.length,correct=quizState.correct,id='attempt-'+Date.now();state.scores.push({id,date:today(),subject:quizState.subject,correct,total,percent:Math.round(correct/total*100),duration:Math.round((Date.now()-quizState.started)/60000),answers:{...quizState.answers},items:quizState.items.map(q=>({id:q.id,s:q.s,type:q.type,q:q.q,o:q.o,a:q.a,e:q.e,outline:q.outline,evidence:q.evidence}))});quizState.items.forEach(q=>{if(quizState.answers[q.id]!==q.a){const t=ALL_TOPICS.find(t=>t.s===q.s&&q.q.toLowerCase().includes(t.name.split(/[ ,:;]/)[0].toLowerCase()));if(t)state.flashcards[t.id]={due:today(),interval:1};}});save();go('#/results/'+id);}
function resetData(){if(!confirm('This will delete your saved study progress, notes, mistakes and results from this browser. Export a backup first. Continue?'))return;localStorage.removeItem(KEY);state=BASE();quizState=null;save();go('#/welcome');toast('Local study progress was reset.');}
function doAction(a,b){
 if(a==='close-modal')hideModal();
 else if(a==='new-note')showModal(noteModal('note'));
 else if(a==='new-mistake')showModal(noteModal('mistake'));
 else if(a==='log-session')newSession();
 else if(a==='regenerate-plan'){makePlanTopics(true);render();toast('Today’s study blocks refreshed.');}
 else if(a==='explore-guest'){state.onboarded=true;save();go('#/dashboard');}
 else if(a==='finish-onboarding'){state.prefs={...state.prefs,...onboardingDraft};state.onboarded=true;save();go('#/dashboard');toast('Your study desk is ready.');}
 else if(a==='export-backup')exportBackup();
 else if(a==='reset-progress')resetData();
 else if(a==='install-prompt'){if(installPrompt)installPrompt.prompt();else toast('Use the browser menu and choose “Install app” or “Add to Home screen”.');}
 else if(a==='start-quiz')startQuiz();
 else if(a==='end-quiz'){quizState=null;go('#/practice');}
 else if(a==='restart-quiz'){const s=quizState?.subject||'ALL';quizState=null;go('#/practice');render();const sel=$('#quiz-subject');if(sel)sel.value=s;}
 else if(a==='next-quiz'){if(quizState.index<quizState.items.length-1){quizState.index++;render();}else finishQuiz();}
 else if(a==='flip-revision'){const el=$('#revision-cues');if(el)el.hidden=!el.hidden;}
 else if(a==='revision-next'){revisionIndex++;render();}
 else if(a==='revision-prev'){revisionIndex=Math.max(0,revisionIndex-1);render();}
 else if(a==='reviewed'){const t=topicById(b);if(t){state.flashcards[t.id]={due:new Date(Date.now()+86400000).toISOString().slice(0,10),interval:1};state.topics[t.id]={...(state.topics[t.id]||{}),status:'Recall passed',updated:today()};save();render();toast('Review saved. Revisit tomorrow.');}}
 else if(a==='topic-revise'){state.flashcards[b]={due:today(),interval:1};save();toast('Added to today’s revision queue.');}
 else if(a==='topic-bookmark'){const id='topic:'+b;state.bookmarks.includes(id)?state.bookmarks=state.bookmarks.filter(x=>x!==id):state.bookmarks.push(id);save();render();}
 else if(a==='reveal-question'){const id=b,cur=state.questionAnswers[id];state.questionAnswers[id]=cur==='shown'?null:'shown';save();render();}
 else if(a==='question-mistake'){showModal(noteModal('mistake'));}
 else if(a==='chat-topic'){const s=$('#chat-subject')?.value||'CN',name=$('#chat-topic')?.value.trim();if(!name){toast('Enter a topic or question first.');return;}window.open(chatLink('Teach me '+name+' in '+(subj(s)?.name||s)+' for BEU B.Tech CSE Semester 4, with examples and an exam-ready answer.'),'_blank','noopener');}
 else if(a==='show-long'){questionType='Long';go('#/pyqs');render();}
}
document.addEventListener('click',e=>{
 const goBtn=e.target.closest('[data-go]');if(goBtn){e.preventDefault();go(goBtn.dataset.go);return;}
 const pageBtn=e.target.closest('[data-page]');if(pageBtn){e.preventDefault();go('#/'+pageBtn.dataset.page);return;}
 if(e.target.closest('#mobile-more')){if(moreOpen)closeMore();else openMore();return;}
 const clearFilters=e.target.closest('[data-action="clear-pyq-filters"]');if(clearFilters){subjectFilter='ALL';questionType='ALL';questionSearch='';pyqYear='ALL';pyqMarks='ALL';pyqPriority='ALL';pyqUnit='ALL';pyqTopic='ALL';pyqSource='ALL';pyqCompletion='ALL';go('#/pyqs');render();return;}
 const action=e.target.closest('[data-action]');if(action){doAction(action.dataset.action,action.dataset.topic||action.dataset.question||'');return;}
 const hours=e.target.closest('[data-onboard-hours]');if(hours){onboardingDraft.hours=Number(hours.dataset.onboardHours);render();return;}
 const mode=e.target.closest('[data-onboard-mode]');if(mode){onboardingDraft.mode=mode.dataset.onboardMode;render();return;}
 const toggle=e.target.closest('[data-plan-toggle]');if(toggle){const id=toggle.dataset.planToggle;state.dayDone[id]=!state.dayDone[id];save();render();return;}
 const quick=e.target.closest('[data-quick-toggle]');if(quick){const t=topicById(quick.dataset.quickToggle);if(t)topicStatusSet(t.id,recalled(t)?'Practiced':'Recall passed');return;}
 const note=e.target.closest('[data-topic-note]');if(note){showModal(noteModal('note',note.dataset.topicNote));return;}
 const mistake=e.target.closest('[data-topic-mistake]');if(mistake){showModal(noteModal('mistake',mistake.dataset.topicMistake));return;}
 const questionMistake=e.target.closest('[data-question-mistake]');if(questionMistake){const q=questionBank().find(x=>x.id===questionMistake.dataset.questionMistake);showModal(noteModal('mistake',''));return;}
 const subjBtn=e.target.closest('[data-subject-filter]');if(subjBtn){subjectFilter=subjBtn.dataset.subjectFilter;render();return;}
 const typeBtn=e.target.closest('[data-type-filter]');if(typeBtn){questionType=typeBtn.dataset.typeFilter;render();return;}
 const bmark=e.target.closest('[data-bookmark]');if(bmark){const id=bmark.dataset.bookmark;state.bookmarks.includes(id)?state.bookmarks=state.bookmarks.filter(x=>x!==id):state.bookmarks.push(id);save();render();toast(state.bookmarks.includes(id)?'Added to saved items.':'Removed from saved items.');return;}
 const unsave=e.target.closest('[data-unsave]');if(unsave){state.bookmarks=state.bookmarks.filter(x=>x!==unsave.dataset.unsave&&x!=='topic:'+unsave.dataset.unsave);save();render();return;}
 const practiceAnswer=e.target.closest('[data-practice-answer]');if(practiceAnswer){const id=practiceAnswer.dataset.practiceAnswer;state.questionAnswers[id]=Number(practiceAnswer.dataset.answer);save();render();return;}
 const quizAnswer=e.target.closest('[data-quiz-answer]');if(quizAnswer&&quizState&&!quizState.done){const q=quizState.items[quizState.index];if(quizState.answers[q.id]===undefined){quizState.answers[q.id]=Number(quizAnswer.dataset.quizAnswer);if(quizState.answers[q.id]===q.a)quizState.correct++;save();render();}return;}
 const answerQuestion=e.target.closest('[data-answer-question]');if(answerQuestion){state.questionAnswers[answerQuestion.dataset.answerQuestion]=Number(answerQuestion.dataset.answer);save();render();return;}
 const reveal=e.target.closest('[data-reveal]');if(reveal){const id=reveal.dataset.reveal;state.questionAnswers[id]=state.questionAnswers[id]==='shown'?null:'shown';save();render();return;}
 const examCheck=e.target.closest('[data-exam-check]');if(examCheck){state.examChecks[examCheck.dataset.examCheck]=examCheck.checked;save();return;}
 const tab=e.target.closest('[data-note-tab]');if(tab){notesTab=tab.dataset.noteTab;render();return;}
 const deleteRecord=e.target.closest('[data-delete-record]');if(deleteRecord){const [kind,id]=deleteRecord.dataset.deleteRecord.split(':');if(confirm('Delete this saved record?')){const key=kind==='mistakes'?'mistakes':'notes';state[key]=state[key].filter(x=>x.id!==id);save();render();}return;}
 const editRecord=e.target.closest('[data-edit-record]');if(editRecord){const [kind,id]=editRecord.dataset.editRecord.split(':');const key=kind==='mistakes'?'mistakes':'notes';showModal(noteModal(key==='mistakes'?'mistake':'note','',id));return;}
 const deleteSession=e.target.closest('[data-delete-session]');if(deleteSession){if(confirm('Delete this study log?')){state.sessions=state.sessions.filter(x=>x.id!==deleteSession.dataset.deleteSession);save();render();}return;}
 const pdfOpen=e.target.closest('[data-pdf-open]');if(pdfOpen){pdfRecord(pdfOpen.dataset.pdfOpen).then(f=>{if(!f)return;const u=URL.createObjectURL(f.blob);if(activePdfUrl)URL.revokeObjectURL(activePdfUrl);activePdfUrl=u;showModal('<div class="modal-backdrop"><section class="modal" style="width:min(920px,100%);height:88vh;display:flex;flex-direction:column"><div class="question-top"><h2 style="margin:0">'+esc(f.name)+'</h2><button class="btn" data-action="close-modal">Close</button></div><iframe title="PDF preview" src="'+u+'" style="border:0;width:100%;flex:1;margin-top:12px;border-radius:10px"></iframe></section></div>');}).catch(()=>toast('Could not open this PDF.'));return;}
 const pdfDl=e.target.closest('[data-pdf-download]');if(pdfDl){pdfRecord(pdfDl.dataset.pdfDownload).then(f=>{const u=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=u;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});return;}
 const pdfDel=e.target.closest('[data-pdf-delete]');if(pdfDel){if(confirm('Remove this PDF from local storage? Original copies elsewhere are not affected.'))getPdfDB().then(db=>new Promise(resolve=>{const r=db.transaction('pdfs','readwrite').objectStore('pdfs').delete(Number(pdfDel.dataset.pdfDelete));r.onsuccess=resolve;})).then(()=>listPdfs());return;}
 if(e.target.matches('[data-dismiss-modal]')&&e.target===e.target.closest('[data-dismiss-modal]')){hideModal();return;}
});
document.addEventListener('change',e=>{
 const st=e.target.closest('[data-topic-status]');if(st){topicStatusSet(st.dataset.topicStatus,st.value);return;}
 if(e.target.id==='pyq-subject-filter'){subjectFilter=e.target.value;pyqUnit='ALL';pyqTopic='ALL';render();return;}
 if(e.target.id==='pyq-unit-filter'){pyqUnit=e.target.value;render();return;}
 if(e.target.id==='pyq-topic-filter'){pyqTopic=e.target.value;render();return;}
 if(e.target.id==='pyq-year-filter'){pyqYear=e.target.value;render();return;}
 if(e.target.id==='pyq-marks-filter'){pyqMarks=e.target.value;render();return;}
 if(e.target.id==='pyq-priority-filter'){pyqPriority=e.target.value;render();return;}
 if(e.target.id==='pyq-source-filter'){pyqSource=e.target.value;render();return;}
 if(e.target.id==='pyq-status-filter'){pyqCompletion=e.target.value;render();return;}
 if(e.target.id==='pdf-upload'){uploadPdfs(e.target.files);e.target.value='';return;}
 if(e.target.id==='backup-import'&&e.target.files?.[0]){importBackup(e.target.files[0]);e.target.value='';return;}
});
document.addEventListener('input',e=>{if(e.target.id==='question-search'){const pos=e.target.selectionStart;questionSearch=e.target.value;const page=route.page;const focusId=e.target.id;const scroll=window.scrollY;render();const input=$('#'+focusId);if(input){input.focus();input.setSelectionRange(pos,pos);window.scrollTo(0,scroll);}return;}if(e.target.id==='onboard-name')onboardingDraft.name=e.target.value;});
document.addEventListener('submit',e=>{
 if(e.target.id==='note-form'){e.preventDefault();const f=e.target,d=new FormData(f),mode=f.dataset.mode==='mistakes'?'mistake':f.dataset.mode,kind=mode==='mistake'?'mistakes':'notes',id=f.dataset.record||'record-'+Date.now(),old=state[kind].find(x=>x.id===id),item={...(old||{}),id,title:String(d.get('title')||'').trim(),body:String(d.get('body')||'').trim(),topic:f.dataset.topic||old?.topic||'',createdAt:old?.createdAt||new Date().toISOString()};if(!item.title||!item.body){toast('Enter both a title and content.');return;}const i=state[kind].findIndex(x=>x.id===id);if(i>=0)state[kind][i]=item;else state[kind].push(item);save();hideModal();render();toast('Saved.');return;}
 if(e.target.id==='session-form'){e.preventDefault();const d=new FormData(e.target);state.sessions.push({id:'session-'+Date.now(),date:today(),createdAt:new Date().toISOString(),minutes:Number(d.get('minutes')),subject:d.get('subject'),note:String(d.get('note')||'').trim()});save();hideModal();render();toast('Study session logged.');return;}
 if(e.target.id==='settings-form'){e.preventDefault();const d=new FormData(e.target);state.prefs={...state.prefs,name:String(d.get('name')||'').trim(),hours:Number(d.get('hours')),mode:d.get('mode'),theme:d.get('theme'),language:d.get('language')};save();makePlanTopics(true);render();toast('Preferences saved.');return;}
});
window.addEventListener('hashchange',()=>{hideModal();render();window.scrollTo(0,0);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;installNav();});
const mobileMore=$('#mobile-more');if(mobileMore)mobileMore.setAttribute('aria-label','More destinations');
$('#open-preferences')?.addEventListener('click',()=>go('#/settings'));
$('#install-button')?.addEventListener('click',()=>doAction('install-prompt'));
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
render();
})();